      if(cnt>0){ int c=0; while(true){ if(x<key[c]){ if(L[c]<0){L[c]=cnt;break;} c=L[c]; } else { if(R[c]<0){R[c]=cnt;break;} c=R[c]; } } }
      cnt++; }
    int k=s.nextInt(), c=0, d=0;
    while(c>=0 && cnt>0){ if(key[c]==k){ System.out.println("FOUND "+d); return; } c = k<key[c]?L[c]:R[c]; d++; }
