using namespace std;
void msort(vector<int>& a,int l,int r){ if(l>=r) return; int m=(l+r)/2; msort(a,l,m); msort(a,m+1,r);
  vector<int> t; int i=l,j=m+1; while(i<=m&&j<=r) t.push_back(a[i]<=a[j]?a[i++]:a[j++]);
  while(i<=m) t.push_back(a[i++]); while(j<=r) t.push_back(a[j++]);
  for(int k=0;k<(int)t.size();k++) a[l+k]=t[k]; }
